			function chkInstIobxSeCd(){
			    
			    var voDsMap = app.lookup("dmSave");
			    
			    if(instIobxSeCd == "G"){
			        // 로그인한기관이 사업관련 기관이면 select box 모두 활성
			        voDsMap.setValue( "IOBX_SE_CD",      ""); // 문서수발신과 내부메일 로직 분리 구분 값 // 내부메일 메뉴 용 B(개인), G(사업) 2가지 UI 에서 전체인 경우 "", 개인:B, 사업:G 으로 넘겨 구분함.
			        app.lookup("cmb1").enabled = true;
			        //app.lookup("cmbSearch2").readOnly = false;
			    }else if(instIobxSeCd == "B"){
			        voDsMap.setValue( "IOBX_SE_CD",      "B"); // 문서수발신과 내부메일 로직 분리 구분 값 // 내부메일 메뉴 용 B(개인), G(사업) 2가지 UI 에서 전체인 경우 "", 개인:B, 사업:G 으로 넘겨 구분함.
			        app.lookup("cmb1").enabled = false;
			        //app.lookup("cmbSearch2").readOnly = true;
			    }
			    
			}


