			    cmnMultifileupload.removeAllFiles();
			    cmnMultifileupload.atfino = "";
			    
			    var cmnMultifileUpload1 = app.lookup("cmnMultifileUpload1");
			    cmnMultifileUpload1.removeAllFiles();
			    cmnMultifileUpload1.atfino = "";
			    
			    var cmnMultifileupload2 = app.lookup("cmnMultifileupload2");
			    cmnMultifileupload2.removeAllFiles();
